const CEFR_IRREGULAR={"built":"build","bought":"buy","brought":"bring","caught":"catch","chose":"choose","chosen":"choose","came":"come","did":"do","done":"do","drew":"draw","drove":"drive","ate":"eat","eaten":"eat","fell":"fall","fallen":"fall","felt":"feel","found":"find","flew":"fly","flown":"fly","forgot":"forget","forgotten":"forget","got":"get","gotten":"get","gave":"give","given":"give","went":"go","gone":"go","grew":"grow","grown":"grow","had":"have","heard":"hear","held":"hold","kept":"keep","knew":"know","known":"know","laid":"lay","led":"lead","left":"leave","lent":"lend","lost":"lose","made":"make","meant":"mean","met":"meet","paid":"pay","put":"put","read":"read","ran":"run","said":"say","saw":"see","seen":"see","sold":"sell","sent":"send","set":"set","shown":"show","shut":"shut","sang":"sing","sat":"sit","slept":"sleep","spoke":"speak","spoken":"speak","spent":"spend","stood":"stand","took":"take","taken":"take","taught":"teach","told":"tell","thought":"think","threw":"throw","thrown":"throw","understood":"understand","wore":"wear","worn":"wear","won":"win","wrote":"write","written":"write","overlaid":"overlay","began":"begin","begun":"begin","broke":"break","broken":"break","drank":"drink","drunk":"drink","rose":"rise","risen":"rise","woke":"wake","woken":"wake","was":"be","were":"be","been":"be","am":"be","is":"be","are":"be","children":"child","men":"man","women":"woman","feet":"foot","teeth":"tooth","geese":"goose","mice":"mouse","people":"person","lives":"life","knives":"knife","wives":"wife","leaves":"leaf","halves":"half","better":"good","best":"good","worse":"bad","worst":"bad","more":"much","most":"much"};

// ── Tra CEFR + loại từ, có lemmatize ────────────────────────────────
// Trả {level:'B2', pos:'v', lemma:'excavate'} hoặc null nếu không có trong từ điển.
const _LVNAME = {'1':'A1','2':'A2','3':'B1','4':'B2','5':'C1','6':'C2'};
const _POSNAME = {n:'noun',v:'verb',j:'adj',r:'adv',p:'prep',d:'det',c:'conj',o:'pron',x:'excl',m:'num'};

function cefrLemma(w, _depth){
  w = String(w||'').toLowerCase().replace(/[^a-z'\-]/g,'');
  if(!w) return null;
  if(CEFR_MAP[w]) return w;
  if(CEFR_IRREGULAR[w] && CEFR_MAP[CEFR_IRREGULAR[w]]) return CEFR_IRREGULAR[w];
  // Luật hậu tố — thử theo thứ tự cụ thể→tổng quát.
  const tries = [];
  if(/ies$/.test(w))      tries.push(w.slice(0,-3)+'y');
  if(/ied$/.test(w))      tries.push(w.slice(0,-3)+'y');
  if(/ier$/.test(w))      tries.push(w.slice(0,-3)+'y');
  if(/iest$/.test(w))     tries.push(w.slice(0,-4)+'y');
  if(/ily$/.test(w))      tries.push(w.slice(0,-3)+'y');
  if(/ves$/.test(w))      tries.push(w.slice(0,-3)+'f', w.slice(0,-3)+'fe');
  if(/(ses|xes|zes|ches|shes)$/.test(w)) tries.push(w.slice(0,-2));
  if(/s$/.test(w) && !/ss$/.test(w))     tries.push(w.slice(0,-1));
  if(/ed$/.test(w))       tries.push(w.slice(0,-2), w.slice(0,-1));
  if(/ing$/.test(w))      tries.push(w.slice(0,-3), w.slice(0,-3)+'e');
  // -ally → -al → gốc:  systematically → systematical → systematic
  if(/ally$/.test(w))     tries.push(w.slice(0,-4)+'al', w.slice(0,-4), w.slice(0,-2));
  if(/ly$/.test(w))       tries.push(w.slice(0,-2), w.slice(0,-2)+'e');
  // -ation/-ition → gốc:  alteration → alter | definition → define
  if(/ations?$/.test(w))  tries.push(w.replace(/ations?$/,''), w.replace(/ations?$/,'ate'), w.replace(/ations?$/,'e'));
  if(/(tion|sion)$/.test(w)) tries.push(w.slice(0,-3)+'e', w.slice(0,-4)+'e', w.slice(0,-4));
  if(/ment$/.test(w))     tries.push(w.slice(0,-4));
  if(/ness$/.test(w))     tries.push(w.slice(0,-4));
  if(/ity$/.test(w))      tries.push(w.slice(0,-3)+'e', w.slice(0,-3));
  if(/al$/.test(w))       tries.push(w.slice(0,-2));
  if(/er$/.test(w))       tries.push(w.slice(0,-2), w.slice(0,-1));
  if(/est$/.test(w))      tries.push(w.slice(0,-3), w.slice(0,-2));
  // Phụ âm đôi: stopped→stop, running→run
  const m = w.match(/^(.*?)([bcdfglmnprst])\2(ed|ing|er|est)$/);
  if(m) tries.push(m[1]+m[2]);
  for(const t of tries) if(t.length>1 && CEFR_MAP[t]) return t;
  // Đệ quy 1 lớp: bóc số nhiều rồi lemmatize tiếp danh từ phái sinh
  // alterations → alteration → alter   (1 luật không bóc nổi 2 hậu tố)
  if(!_depth && /s$/.test(w) && !/ss$/.test(w)){
    const r = cefrLemma(w.slice(0,-1), 1);
    if(r) return r;
  }
  return null;
}

function cefrOf(word){
  const lem = cefrLemma(word);
  if(!lem) return null;
  const codes = CEFR_MAP[lem].split('|');
  const c = codes[0];   // cấp dễ nhất — tránh gắn cờ "từ khó" oan
  return { level:_LVNAME[c[0]], pos:_POSNAME[c[1]]||'', lemma:lem, allPos:codes.map(x=>_POSNAME[x[1]]) };
}
